 function updateTeamStatus(){ $('teamStatus').textContent=battle.phase==='active'?'試合中 · 3被弾で脱落':battle.phase==='finished'?'試合終了 · 次の試合を準備中':battle.startAt?'自動開始まで '+Math.max(0,Math.ceil((battle.startAt-get().now)/1000))+'秒':'2人以上の入場を待っています';}
