   if(zone||s.cameraMode==='first'){const bob=Math.sin(s.time*9)*Math.min(.014,s.speed*.004);camera.position.copy(eye);camera.position.y+=bob;camera.lookAt(eye.clone().add(direction));}
   else{const right=new THREE.Vector3(Math.cos(s.yaw),0,-Math.sin(s.yaw)),target=eye.clone().addScaledVector(direction,80),desired=eye.clone().addScaledVector(right,.5).addScaledVector(direction,-2.4);camera.position.copy(s.world.cameraPosition(eye,desired,.18));camera.lookAt(target);}
